#include <iostream>
#include <string>
using namespace std;

class House {
private:
    string houseName, city, state;
    int houseNumber, numberOfRooms;
    float width, height, area;

public:
    // Default Constructor
    House() {
        houseName = "Unknown"; city = "Unknown"; state = "Unknown";
        houseNumber = 0; numberOfRooms = 0; width = 0.0; height = 0.0; area = 0.0;
    }

    // Parameterized Constructor
    House(string hName, int hNum, string c, string s, float w, float h, int rooms) {
        houseName = hName; houseNumber = hNum; city = c; state = s;
        width = w; height = h; numberOfRooms = rooms;
        area = width * height;
    }

    void displayDetails() {
        cout << "House: " << houseName << " (#" << houseNumber << ")\n";
        cout << "Location: " << city << ", " << state << "\n";
        cout << "Dimensions: " << width << "x" << height << " | Area: " << area << " sq units\n";
        cout << "Rooms: " << numberOfRooms << "\n-----------------------\n";
    }
};

int main() {
    House h1; // Calls default constructor
    cout << "Default Details:\n";
    h1.displayDetails();

    House h2("Rose Villa", 101, "Chennai", "TN", 30.5, 40.0, 4); // Calls parameterized constructor
    cout << "Parameterized Details:\n";
    h2.displayDetails();

    return 0;
}
