```cpp
#include <iostream>
#include <string>
using namespace std;

// Base Class
class Person {
private: 
    string aadhar; // Not inherited
protected:
    int age;       // Inherited, behaves as protected
public:
    string name;   // Inherited, behaves as public in 'public' inheritance
    void setPersonDetails(string n, int a, string ad) { name = n; age = a; aadhar = ad; }
};

// Level 1 Derived Class
class Employee : public Person { // Public Inheritance: public->public, protected->protected
protected:
    int empId;
public:
    void setEmployeeDetails(int id) { empId = id; }
};

// Level 2 Derived Class
class Teacher : protected Employee { // Protected Inheritance: public & protected -> protected
private:
    string subject;
public:
    void setTeacherDetails(string sub) { subject = sub; }
    void display() {
        // Can access inherited protected & public members
        cout << "Name: " << name << " | Age: " << age 
             << " | EmpID: " << empId << " | Subject: " << subject << endl;
        // cout << aadhar; // ERROR: Private member of Person
    }
    // Helper since name, age, empId are now protected in Teacher
    void setup(string n, int a, string ad, int id, string sub) {
        setPersonDetails(n, a, ad); 
        setEmployeeDetails(id);
        setTeacherDetails(sub);
    }
};

int main() {
    Teacher t;
    t.setup("Alice", 35, "1234", 1001, "Maths");
    t.display();
    // t.name = "Bob"; // ERROR: 'name' is protected in Teacher due to protected inheritance
    return 0;
}
```
**Explanation:**
- **Public Inheritance:** Base public -> Derived public; Base protected -> Derived protected.
- **Protected Inheritance:** Base public & protected -> Derived protected.
- **Private Inheritance:** Base public & protected -> Derived private.
- **Data:** Private data is never accessible in derived classes. Protected is accessible in derived classes but not outside. Public is accessible everywhere.

Function overriding occurs when a derived class provides a specific implementation for a function that is already defined in its base class.
```cpp
#include <iostream>
using namespace std;

class Animal {
public:
    virtual void sound() { cout << "Animal makes a sound" << endl; }
};

class Dog : public Animal {
public:
    // Overriding the base class method
    void sound() override { cout << "Dog barks" << endl; }
};

int main() {
    Animal* a = new Dog();
    a->sound(); // Output: Dog barks (Runtime polymorphism)
    delete a;
    return 0;
}
