using namespace std;

int main() {
    vector<int> v1, v2;
    int n, elem;

    cout << "Enter number of elements for vectors: ";
    cin >> n;

    cout << "Enter elements for Vector 1:\n";
    for (int i = 0; i < n; i++) {
        cin >> elem;
        v1.push_back(elem);
    }

    cout << "Enter elements for Vector 2:\n";
    for (int i = 0; i < n; i++) {
        cin >> elem;
        v2.push_back(elem);
    }

    cout << "\nBefore Swapping:\nVector 1: ";
    for (int x : v1) cout << x << " ";
    cout << "\nVector 2: ";
    for (int x : v2) cout << x << " ";

    // STL function to swap vectors
    v1.swap(v2);

    cout << "\n\nAfter Swapping:\nVector 1: ";
    for (int x : v1) cout << x << " ";
    cout << "\nVector 2: ";
    for (int x : v2) cout << x << " ";
    cout << endl;

    return 0;
}
