#include <iostream>
#include <list>
using namespace std;

// User defined function to print list
void print_list(const list<int>& lst) {
    for (int val : lst) {
        cout << val << " ";
    }
    cout << endl;
}

int main() {
    list<int> myList = {20, 40, 30};
    cout << "Initial List: "; print_list(myList);

    // (i) push_front()
    myList.push_front(10);
    cout << "After push_front(10): "; print_list(myList);

    // (ii) insert() - Insert 25 after the first element
    auto it = myList.begin();
    advance(it, 1); 
    myList.insert(it, 25);
    cout << "After insert(25): "; print_list(myList);

    // (iii) sort()
    myList.sort();
    cout << "After sort(): "; print_list(myList);

    // (iv) pop_back()
    myList.pop_back();
    cout << "After pop_back(): "; print_list(myList);

    return 0;
}
```

1.  **`for_each()`:** Applies a given function to every element in a range.
    ```cpp
vector<int> v = {1, 2, 3};
    for_each(v.begin(), v.end(), [](int &n){ n *= 2; }); // Modifies v to {2, 4, 6}
```
2.  **`transform()`:** Applies a function to elements of one (or two) ranges and stores the result in a destination range.
    ```cpp
vector<int> v1 = {1, 2, 3}, v2(3);
    transform(v1.begin(), v1.end(), v2.begin(), [](int n){ return n+1; }); // v2 becomes {2, 3, 4}
```
3.  **`merge()`:** Merges two sorted ranges into a single sorted destination range.
    ```cpp
vector<int> a = {1, 3}, b = {2, 4}, result(4);
    merge(a.begin(), a.end(), b.begin(), b.end(), result.begin()); // result is {1, 2, 3, 4}
```
4.  **`search()`:** Finds the first occurrence of a sub-range within another main range.
    ```cpp
vector<int> main = {10, 20, 30, 40}, sub = {20, 30};
    auto it = search(main.begin(), main.end(), sub.begin(), sub.end());
    // 'it' points to the element '20' in 'main'
```

