#include <iostream>
using namespace std;

// Class Template for Account Verification operations
template <class T>
class AccountChecker {
private:
    T value1;
    T value2;

public:
    // Constructor to initialize values
    AccountChecker(T v1, T v2) {
        value1 = v1;
        value2 = v2;
    }

    T add() {
        return value1 + value2;
    }

    T subtract() {
        return value1 - value2;
    }

    T multiply() {
        return value1 * value2;
    }

    T divide() {
        if (value2 != 0) {
            return value1 / value2;
        } else {
            cout << "Error: Division by Zero! ";
            return 0;
        }
    }

    void displayResults() {
        cout << "Values: " << value1 << " and " << value2 << endl;
        cout << "Addition (Credit/Deposit): " << add() << endl;
        cout << "Subtraction (Debit/Withdrawal): " << subtract() << endl;
        cout << "Multiplication (Interest Calc): " << multiply() << endl;
        cout << "Division (Split amounts): " << divide() << endl;
        cout << "-----------------------------------\n";
    }
};

int main() {
    cout << "--- Bank Account Verification Tool ---\n\n";

    // Using integers for basic amounts
    cout << "Checking basic integer amounts:\n";
    AccountChecker<int> intCalc(5000, 250);
    intCalc.displayResults();

    // Using floats for amounts with decimals/paise
    cout << "Checking precise float amounts:\n";
    AccountChecker<float> floatCalc(10500.50f, 150.25f);
    floatCalc.displayResults();

    return 0;
}
```
